mapper.select:

SELECT id,
       kb_id,
       doc_id,
       chunk_index,
       text_content,
       source,
       1 - (embedding <=> #{query,typeHandler=com.xtsh.ragchunk.mapper.typehandler.PgVectorTypeHandler}) AS score
FROM chunk
WHERE kb_id = #{kbId}
  AND 1 - (embedding <=> #{query,typeHandler=com.xtsh.ragchunk.mapper.typehandler.PgVectorTypeHandler}) >= #{minScore}
ORDER BY embedding <=> #{query,typeHandler=com.xtsh.ragchunk.mapper.typehandler.PgVectorTypeHandler}
LIMIT #{topK}

SELECT id, kb_id, doc_id, chunk_index, text_content, source, embedding
FROM chunk
WHERE kb_id = #{kbId}
